-- Hosted Test compatible. Every fixture and mutation rolls back; no providers.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,pg_catalog;
select plan(1);
create temp table billing_checks(label text);
create temp table billing_publication_probe(id uuid,manager_id uuid,name text,status text,publication_state text);
create trigger billing_publication_probe after update of publication_state on billing_publication_probe for each row execute function private.billing_register_shop();
create function pg_temp.ba(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'BILLING_ASSERT: %',label;end if;insert into billing_checks values(label);end$$;
create function pg_temp.be(action text,data jsonb,code text)returns boolean language plpgsql as $$begin perform public.subscription_billing(action,data);return false;exception when others then if sqlerrm<>code then raise exception 'Unexpected %; wanted %',sqlerrm,code;end if;return true;end$$;
do $test$
declare
 m uuid:=gen_random_uuid();m2 uuid:=gen_random_uuid();bm uuid:=gen_random_uuid();cu uuid:=gen_random_uuid();ad uuid:=gen_random_uuid();ag uuid:=gen_random_uuid();
 ms uuid:=gen_random_uuid();m2s uuid:=gen_random_uuid();bs uuid:=gen_random_uuid();cs uuid:=gen_random_uuid();ads uuid:=gen_random_uuid();ags uuid:=gen_random_uuid();f uuid:=gen_random_uuid();f2 uuid:=gen_random_uuid();
 service uuid:=gen_random_uuid();shop uuid:=gen_random_uuid();shop2 uuid:=gen_random_uuid();outside uuid:=gen_random_uuid();business uuid;other_business uuid;barber uuid:=gen_random_uuid();pending uuid:=gen_random_uuid();chair uuid:=gen_random_uuid();managed uuid:=gen_random_uuid();
 mc text;ac text;gc text;result jsonb;input jsonb;one jsonb;two jsonb;gid uuid;cid uuid;now_at timestamptz:=clock_timestamp();today date:=(clock_timestamp()at time zone'Asia/Kuwait')::date;old_trial timestamptz;
begin
 insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data)values(m,m||'@example.test',now(),'{"role":"manager"}'),(m2,m2||'@example.test',now(),'{"role":"manager"}'),(bm,bm||'@example.test',now(),'{"role":"barber"}'),(cu,cu||'@example.test',now(),'{"role":"customer"}'),(ad,ad||'@example.test',now(),'{"role":"admin"}'),(ag,ag||'@example.test',now(),'{"role":"agent"}');
 insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at)values(f,ad,'totp','verified','synthetic-test-only',now(),now()),(f2,ag,'totp','verified','synthetic-test-only',now(),now());
 insert into auth.sessions(id,user_id,aal,factor_id)values(ms,m,'aal1',null),(m2s,m2,'aal1',null),(bs,bm,'aal1',null),(cs,cu,'aal1',null),(ads,ad,'aal2',f),(ags,ag,'aal2',f2);
 mc:=jsonb_build_object('sub',m,'session_id',ms,'role','authenticated','aal','aal1','app_metadata',jsonb_build_object('role','manager'))::text;
 ac:=jsonb_build_object('sub',ad,'session_id',ads,'role','authenticated','aal','aal2')::text;
 gc:=jsonb_build_object('sub',ag,'session_id',ags,'role','authenticated','aal','aal2')::text;
 perform set_config('request.jwt.claims','{}',true);
 insert into public.branches(id,manager_id,name,status)values(shop,m,'Subscription QA One','active'),(shop2,m,'Subscription QA Two','active'),(outside,m2,'Subscription QA Outside','active');
 select business_id into business from private.billing_shops where branch_id=shop;
 select business_id into other_business from private.billing_shops where branch_id=outside;
 perform pg_temp.ba(business=(select business_id from private.billing_shops where branch_id=shop2),'same manager shops share business');
 perform pg_temp.ba(business<>other_business,'separate businesses');
 perform pg_temp.ba(private.billing_price(0,'monthly')=25000 and private.billing_price(2,'monthly')=25000,'zero/two monthly minimum');
 perform pg_temp.ba(private.billing_price(3,'monthly')=30000 and private.billing_price(6,'yearly')=600000,'integer monthly/yearly price');
 insert into public.services(id,branch_id,name,duration,price)values(service,shop,'QA Cut',30,3);
 insert into public.barbers(id,user_id,branch_id,name,status,invite_status,service_ids)values(barber,bm,shop,'Accepted','active','accepted',array[service]),(pending,null,shop,'Pending','inactive','pending',array[service]);
 perform set_config('request.jwt.claims',mc,true);
 insert into public.barbers(id,user_id,branch_id,name,status,manager_chair,service_ids)values(chair,m,shop,'My Chair','inactive',true,array[service]);
 update public.barbers set status='active',availability='{"monday":{"enabled":true,"start":"09:00","end":"17:00"}}'where id=chair;
 insert into public.barbers(id,branch_id,name,status,management_mode,service_ids)values(managed,shop,'Managed','active','managed',array[service]);
 perform pg_temp.ba(private.billing_active_count(business)=3,'accepted, managed, chair count; pending excluded');
 perform set_config('request.jwt.claims',mc,true);
 execute 'set local role authenticated';
 result:=public.subscription_billing('businesses');
 execute 'reset role';
 perform pg_temp.ba(jsonb_array_length(result->'rows')=1,'manager sees own business only');
 perform pg_temp.ba(pg_temp.be('detail',jsonb_build_object('businessId',other_business),'BILLING_FORBIDDEN'),'cross-business read denied');
 perform pg_temp.ba(pg_temp.be('grant',jsonb_build_object('businessId',business),'BILLING_FORBIDDEN'),'manager cannot grant access');
 perform pg_temp.ba(pg_temp.be('codes','{}','BILLING_FORBIDDEN'),'manager cannot list private codes');
 perform pg_temp.ba(pg_temp.be('code-history',jsonb_build_object('codeId',gen_random_uuid()),'BILLING_FORBIDDEN'),'manager cannot read code history');
 result:=public.subscription_billing('quote',jsonb_build_object('businessId',business,'count',100,'priceFils',1,'frequency','monthly'));
 perform pg_temp.ba(result->>'count'='3'and result->>'subtotalFils'='30000','client count/price ignored');
 perform pg_temp.ba(result->>'settled'='false'and result->>'gatewayConnected'='false','no settlement/gateway');
 input:=jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'frequency','yearly','renewalRequested',false,'revision',1);
 one:=public.subscription_billing('preferences',input);two:=public.subscription_billing('preferences',input);
 perform pg_temp.ba(one=two and(select revision from private.billing_subscriptions where business_id=business)=2,'identical retry exactly once');
 perform pg_temp.ba(pg_temp.be('preferences',input||'{"frequency":"monthly"}','BILLING_RETRY_CHANGED'),'changed retry denied');
 perform pg_temp.ba(pg_temp.be('preferences',input||jsonb_build_object('requestId',gen_random_uuid()),'BILLING_STALE'),'stale preference denied');
 perform pg_temp.ba((select frequency='monthly'and next_frequency='yearly'and not renewal_requested from private.billing_subscriptions where business_id=business),'schedule does not replace current term');
 perform set_config('request.jwt.claims','{}',true);
 -- Publication readiness is tested by the existing publishing suite; use the
 -- same trigger with only this fixture's state, under the owner database role.
 insert into billing_publication_probe values(shop,m,'QA','active','draft');
 update billing_publication_probe set publication_state='published'where id=shop;
 select trial_started_at into old_trial from private.billing_subscriptions where business_id=business;
 perform pg_temp.ba(old_trial is not null and private.billing_access(business)->>'status'='trial','first publish starts trial');
 perform pg_temp.ba(private.billing_access(business,old_trial+interval'14 days')->>'status'='expired','trial ends at exact deadline, no grace');
 update private.billing_subscriptions set trial_started_at=now_at-interval'20 days',trial_ends_at=now_at-interval'6 days'where business_id=business;
 update private.billing_subscriptions set period_started_at=now_at-interval'1 month',period_ends_at=now_at,renewal_requested=true,renewal_failed_at=now_at where business_id=business;
 perform pg_temp.ba(private.billing_access(business,now_at+interval'71 hours 59 minutes')->>'status'='grace','failed paid renewal inside grace');
 perform pg_temp.ba(private.billing_access(business,now_at+interval'72 hours')->>'status'='expired','72-hour boundary exclusive');
 update private.billing_subscriptions set renewal_requested=false where business_id=business;
 perform pg_temp.ba(private.billing_access(business,now_at+interval'1 hour')->>'status'='expired','voluntary nonrenewal cannot grant paid grace');
 update private.billing_subscriptions set trial_started_at=now_at-interval'20 days',trial_ends_at=now_at-interval'6 days'where business_id=business;
 perform pg_temp.ba(private.billing_access(business,now_at+interval'1 hour')->>'status'='expired','cancelled renewal, no other access');
 perform set_config('request.jwt.claims',ac,true);
 input:=jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'kind','manual','startsOn',today,'endsOn',today+7,'reason','QA manual','branchIds',jsonb_build_array());
 perform pg_temp.ba(pg_temp.be('grant',input,'BILLING_BRANCH_REQUIRED'),'manual needs shop');
 perform pg_temp.ba(pg_temp.be('grant',input||jsonb_build_object('branchIds',jsonb_build_array(outside)),'BILLING_BRANCH_REQUIRED'),'foreign grant shop denied');
 result:=public.subscription_billing('grant',input||jsonb_build_object('branchIds',jsonb_build_array(shop)));gid:=(result->>'id')::uuid;
 perform pg_temp.ba(private.billing_access(business)->>'status'='manual','manual access is not full');
 perform pg_temp.ba(private.billing_access(business)->>'fullAccess'='false'and private.billing_access(business)->'manualBranchIds'=jsonb_build_array(shop),'manual exception selected shop only');
 perform pg_temp.ba(private.billing_access(business)->>'enforced'='false','foundation never enables enforcement');
 perform public.subscription_billing('revoke-grant',jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'grantId',gid,'reason','QA revoke'));
 perform pg_temp.ba(private.billing_access(business)->>'status'='expired','revocation restores underlying state');
 perform pg_temp.ba((select revoked_at is not null from private.billing_access_grants where id=gid),'revoked grant preserved');
 result:=public.subscription_billing('grant',input||jsonb_build_object('requestId',gen_random_uuid(),'kind','full','branchIds','[]'::jsonb));gid:=(result->>'id')::uuid;
 perform pg_temp.ba(private.billing_access(business)->>'status'='complimentary','full grant works');
 update private.billing_subscriptions set period_started_at=now_at-interval'1 day',period_ends_at=now_at+interval'29 days',renewal_failed_at=null where business_id=business;
 perform pg_temp.ba(private.billing_access(business)->>'status'='active','paid time takes priority');
 perform public.subscription_billing('revoke-grant',jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'grantId',gid,'reason','QA revoke full'));
 perform pg_temp.ba(private.billing_access(business)->>'status'='active','removing grant preserves paid time');
 input:=jsonb_build_object('requestId',gen_random_uuid(),'code','QA'||replace(gen_random_uuid()::text,'-','')::varchar(10),'kind','percent','value',20,'eligibility','monthly','payments',3,'expiresOn',today+30,'limit',1,'reason','QA code');
 result:=public.subscription_billing('create-code',input);cid:=(result->>'id')::uuid;
 perform set_config('request.jwt.claims',mc,true);
 result:=public.subscription_billing('quote',jsonb_build_object('businessId',business,'frequency','monthly','code',input->>'code'));
 perform pg_temp.ba(result->>'totalFils'='24000'and result->>'discountPayments'='3','discount after minimum, correct duration');
 perform pg_temp.ba((select count(*)from private.billing_redemptions where code_id=cid)=0,'quote never redeems');
 perform pg_temp.ba(pg_temp.be('quote',jsonb_build_object('businessId',business,'frequency','yearly','code',input->>'code'),'BILLING_CODE_INELIGIBLE'),'yearly cannot reuse monthly code');
 perform set_config('request.jwt.claims',gc,true);
 perform public.subscription_billing('toggle-code',jsonb_build_object('requestId',gen_random_uuid(),'codeId',cid,'enabled',false,'reason','QA Admin pause'));
 perform pg_temp.ba((select not enabled from private.billing_discount_codes where id=cid),'renamed Admin can pause');
 result:=public.subscription_billing('code-history',jsonb_build_object('codeId',cid));
 perform pg_temp.ba(jsonb_array_length(result->'rows')=2,'Admin sees created/paused code audit');
 perform set_config('request.jwt.claims',mc,true);
 perform pg_temp.ba(pg_temp.be('quote',jsonb_build_object('businessId',business,'frequency','monthly','code',input->>'code'),'BILLING_CODE_UNAVAILABLE'),'paused code rejected');
 perform set_config('request.jwt.claims',ac,true);
 perform pg_temp.ba(pg_temp.be('transfer',jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'managerId',m2,'reason','QA foreign'),'BILLING_MANAGER_REQUIRED'),'unassigned manager rejected');
 perform set_config('request.jwt.claims','{}',true);update public.branches set manager_id=m2 where id=shop2;
 perform set_config('request.jwt.claims',ac,true);
 perform public.subscription_billing('transfer',jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'managerId',m2,'reason','QA assigned transfer'));
 perform set_config('request.jwt.claims',mc,true);
 result:=public.subscription_billing('detail',jsonb_build_object('businessId',business));
 perform pg_temp.ba(result->>'canManage'='false'and result->>'managerId'=m2::text,'old billing manager read-only');
 perform pg_temp.ba(result->>'periodEndsAt'=(select to_jsonb(period_ends_at)#>>'{}'from private.billing_subscriptions where business_id=business),'transfer preserves paid term');
 perform pg_temp.ba(pg_temp.be('preferences',jsonb_build_object('businessId',business,'requestId',gen_random_uuid()),'BILLING_FORBIDDEN'),'old billing manager cannot mutate');

 perform pg_temp.ba(jsonb_array_length(result->'history')=0 and jsonb_array_length(result->'invoices')=0,'other manager receives no audit/invoices');
 perform set_config('request.jwt.claims','{}',true);
 insert into public.branches(id,manager_id,name,status)values(gen_random_uuid(),m,'New shop after billing transfer','active')returning id into outside;
 perform pg_temp.ba((select business_id<>business from private.billing_shops where branch_id=outside),'past origin cannot append shops to transferred billing');
 perform pg_temp.ba((select billing_manager_id=m from private.billing_businesses where id=(select business_id from private.billing_shops where branch_id=outside)),'new shop has current manager as billing owner');
 perform pg_temp.ba(private.billing_price(10000,'yearly')=1000000000,'large team integer price');
 perform set_config('request.jwt.claims',(ac::jsonb||'{"aal":"aal1"}')::text,true);
 perform pg_temp.ba(pg_temp.be('businesses','{}','BILLING_FORBIDDEN'),'Admin requires second factor');
 perform set_config('request.jwt.claims',ac,true);
 perform pg_temp.ba(pg_temp.be('grant',jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'kind','full','startsOn',today,'endsOn',today,'reason','QA equal'),'BILLING_INVALID_DATES'),'equal grant dates denied');
 perform pg_temp.ba(pg_temp.be('grant',jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'kind','full','startsOn',today-1,'endsOn',today+1,'reason','QA past'),'BILLING_INVALID_DATES'),'past grant denied');
 perform pg_temp.ba(pg_temp.be('grant',jsonb_build_object('businessId',business,'requestId',gen_random_uuid(),'kind','full','startsOn',today,'endsOn',today+1,'reason',''),'BILLING_REASON_REQUIRED'),'blank reason denied');
 perform public.subscription_billing('toggle-code',jsonb_build_object('requestId',gen_random_uuid(),'codeId',cid,'enabled',true,'reason','QA enable'));
 update private.billing_discount_codes set kind='fixed',value=999999 where id=cid;
 perform set_config('request.jwt.claims',mc,true);
 result:=public.subscription_billing('quote',jsonb_build_object('businessId',business,'frequency','monthly','code',input->>'code'));
 perform pg_temp.ba(result->>'totalFils'='0','fixed discount capped at subtotal');
 update private.billing_discount_codes set kind='percent',value=33 where id=cid;
 result:=public.subscription_billing('quote',jsonb_build_object('businessId',business,'frequency','monthly','code',input->>'code'));
 perform pg_temp.ba(result->>'totalFils'='20100','percentage uses integer fils');
 update private.billing_discount_codes set expires_at=clock_timestamp()-interval'1 second'where id=cid;
 perform pg_temp.ba(pg_temp.be('quote',jsonb_build_object('businessId',business,'frequency','monthly','code',input->>'code'),'BILLING_CODE_UNAVAILABLE'),'expired code rejected');
 update private.billing_discount_codes set expires_at=clock_timestamp()+interval'1 day'where id=cid;
 insert into private.billing_invoices(business_id,state,subtotal_fils,discount_fils,period_starts_at,period_ends_at)values(other_business,'paid',25000,5000,now_at,now_at+interval'1 month')returning id into gid;
 insert into private.billing_redemptions(code_id,business_id,invoice_id)values(cid,other_business,gid);
 perform pg_temp.ba(pg_temp.be('quote',jsonb_build_object('businessId',business,'frequency','monthly','code',input->>'code'),'BILLING_CODE_USED'),'global one-use code exhausted');
 perform pg_temp.ba((select count(*)from private.billing_invoices where business_id=business)=0,'grant/quote/transfer never invent paid invoices');
 perform set_config('request.jwt.claims',ac,true);
 result:=public.subscription_billing('codes');perform pg_temp.ba(jsonb_array_length(result->'rows')>=1,'Admin code list works');
 result:=public.subscription_billing('businesses',jsonb_build_object('query','Subscription QA','limit',1));perform pg_temp.ba(jsonb_array_length(result->'rows')=2 and(result->>'hasMore')::boolean,'bounded list includes one lookahead');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',cu,'session_id',cs,'aal','aal1','app_metadata',jsonb_build_object('role','admin'))::text,true);
 perform pg_temp.ba(pg_temp.be('businesses','{}','BILLING_FORBIDDEN'),'customer forged admin claim denied');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',bm,'session_id',bs)::text,true);
 perform pg_temp.ba(pg_temp.be('businesses','{}','BILLING_FORBIDDEN'),'barber denied');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',m,'session_id',gen_random_uuid())::text,true);
 perform pg_temp.ba(pg_temp.be('businesses','{}','BILLING_FORBIDDEN'),'stale session denied');
 perform set_config('request.jwt.claims',mc,true);insert into private.account_revoked_sessions(session_id,user_id)values(ms,m);
 perform pg_temp.ba(pg_temp.be('businesses','{}','BILLING_FORBIDDEN'),'revoked session denied');
 perform pg_temp.ba(not has_table_privilege('authenticated','private.billing_subscriptions','update'),'no direct financial writes');
 perform pg_temp.ba(not has_function_privilege('anon','public.subscription_billing(text,jsonb)','execute'),'anonymous API denied');
 perform pg_temp.ba(not has_schema_privilege('authenticated','private','usage'),'existing private schema stays closed');
 perform pg_temp.ba((select count(*)from private.billing_audit where business_id=business)>=5,'audit persisted for changes');
end $test$;
select ok((select count(*)from billing_checks)>=40,'subscription foundation scenario suite');
select jsonb_build_object('scenarios',count(*),'result','passed','persistentFixtureWrites',false) subscription_result from billing_checks;
select *from finish();
rollback;
